rollback.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM modeling_model_spec WHERE contract_version = 2)
       OR EXISTS (SELECT 1 FROM modeling_model_spec_revision WHERE contract_version = 2) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_SPEC_V2_DATA_EXISTS';
    END IF;
    IF EXISTS (
        SELECT 1 FROM modeling_model_spec
         WHERE object_id IS NULL OR process_id IS NULL
    ) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_LEGACY_MODEL_IDENTITY_IS_NULL';
    END IF;
    IF EXISTS (SELECT 1 FROM modeling_model_spec_revision WHERE spec_json IS NULL) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_LEGACY_REVISION_PAYLOAD_IS_NULL';
    END IF;
END $$;

ALTER TABLE modeling_model_spec_revision DROP CONSTRAINT IF EXISTS ck_model_spec_revision_payload;
ALTER TABLE modeling_model_spec_revision DROP CONSTRAINT IF EXISTS ck_model_spec_revision_contract_version;
ALTER TABLE modeling_model_spec DROP CONSTRAINT IF EXISTS ck_model_spec_v2_json_shapes;
ALTER TABLE modeling_model_spec DROP CONSTRAINT IF EXISTS ck_model_spec_v2_type_context;
ALTER TABLE modeling_model_spec DROP CONSTRAINT IF EXISTS ck_model_spec_v2_identity;
ALTER TABLE modeling_model_spec DROP CONSTRAINT IF EXISTS ck_model_spec_contract_version;

changeSet.sql:
CREATE UNIQUE INDEX uk_model_spec_v2_idempotency
    ON modeling_model_spec (tenant_id, idempotency_key)
    WHERE contract_version = 2 AND idempotency_key IS NOT NULL;
CREATE UNIQUE INDEX uk_model_spec_v2_plan_name
    ON modeling_model_spec (tenant_id, plan_id, lower(name))
    WHERE contract_version = 2;
CREATE INDEX idx_model_spec_v2_plan
    ON modeling_model_spec (tenant_id, plan_id, model_type, status)
    WHERE contract_version = 2;
CREATE INDEX idx_model_spec_v2_domain
    ON modeling_model_spec (tenant_id, domain_id, model_type)
    WHERE contract_version = 2;
CREATE INDEX idx_model_spec_v2_activity
    ON modeling_model_spec (tenant_id, business_activity_ref)
    WHERE contract_version = 2 AND business_activity_ref IS NOT NULL;
CREATE INDEX idx_model_spec_revision_tenant
    ON modeling_model_spec_revision (tenant_id, model_spec_id, revision DESC);

rollback.sql:
DROP INDEX IF EXISTS idx_model_spec_revision_tenant;
DROP INDEX IF EXISTS idx_model_spec_v2_activity;
DROP INDEX IF EXISTS idx_model_spec_v2_domain;
DROP INDEX IF EXISTS idx_model_spec_v2_plan;
DROP INDEX IF EXISTS uk_model_spec_v2_plan_name;
DROP INDEX IF EXISTS uk_model_spec_v2_idempotency;
